function useModalFocus<T extends HTMLElement>(isOpen: boolean, onClose: () => void) {
  const containerRef = useRef<T>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  const onCloseRef = useRef(onClose);

  useEffect(() => {
    onCloseRef.current = onClose;
  }, [onClose]);

  useEffect(() => {
    if (!isOpen) return;
    previousFocusRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const container = containerRef.current;
    if (!container) return;

    const focusableSelector = 'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
    const focusables = () => Array.from(container.querySelectorAll<HTMLElement>(focusableSelector)).filter((element) => !element.hasAttribute("hidden") && element.getAttribute("aria-hidden") !== "true");
    const initial = focusables()[0] ?? container;
    initial.focus();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onCloseRef.current();
        return;
      }
      if (event.key !== "Tab") return;
      const items = focusables();
      if (items.length === 0) {
        event.preventDefault();
        container.focus();
        return;
      }
      const first = items[0];
      const last = items[items.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      previousFocusRef.current?.focus();
    };
  }, [isOpen]);

  return containerRef;
}

function ConfirmModal({ isOpen, title, message, confirmLabel = "Confirmar", cancelLabel = "Cancelar", onConfirm, onCancel, variant = "danger" }: { isOpen: boolean; title: string; message: string; confirmLabel?: string; cancelLabel?: string; onConfirm: () => void; onCancel: () => void; variant?: "danger" | "info"; }) {
  const titleId = useId();
  const descriptionId = useId();
  const dialogRef = useModalFocus<HTMLDivElement>(isOpen, onCancel);
  if (!isOpen) return null;
  return <div className="confirm-overlay" onClick={onCancel}><div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} aria-describedby={descriptionId} tabIndex={-1} className="confirm-card space-y-4" onClick={(e) => e.stopPropagation()}><div className="flex items-start gap-3"><div className={cn("w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0", variant === "danger" ? "bg-error/15" : "bg-brand-primary/15")}><AlertTriangle aria-hidden="true" className={cn("w-5 h-5", variant === "danger" ? "text-error" : "text-brand-primary")} /></div><div><h3 id={titleId} className="font-bold text-base text-white">{title}</h3><p id={descriptionId} className="text-sm text-white/60 mt-1">{message}</p></div></div><div className="flex justify-end gap-2 pt-2"><button onClick={onCancel} className="btn-secondary text-xs px-4 py-2">{cancelLabel}</button><button onClick={onConfirm} className={cn("px-4 py-2 rounded-lg text-xs font-semibold transition-all", variant === "danger" ? "bg-error hover:bg-error/80 text-white" : "btn-primary")}>{confirmLabel}</button></div></div></div>;
}

function StyledCheckbox({ checked, onChange, label }: { checked: boolean; onChange: (checked: boolean) => void; label: string; }) {
  return <button type="button" role="checkbox" aria-checked={checked} onClick={() => onChange(!checked)} className={cn("checkbox-styled", checked && "checked")}><span className="check-icon" aria-hidden="true">{checked && <Check className="w-3 h-3 text-white" />}</span><span>{label}</span></button>;
}

function CurrencyInput({ value, onChange, label, required = false }: { value: number; onChange: (val: number) => void; label: string; required?: boolean; }) {
  const [draftValue, setDraftValue] = useState<string | null>(null);
  const inputId = useId();
  const displayValue = draftValue ?? String(value);
  return <div><label htmlFor={inputId} className="block text-xs font-medium text-white/70 mb-1">{label}</label><input id={inputId} type="text" inputMode="decimal" required={required} value={displayValue} onChange={(e) => { const raw = e.target.value; if (raw === "" || raw === "-") { setDraftValue(raw); return; } if (/^\d*\.?\d*$/.test(raw)) { setDraftValue(raw); const parsed = parseFloat(raw); if (!isNaN(parsed)) onChange(parsed); } }} onBlur={() => { const parsed = parseFloat(displayValue); if (isNaN(parsed) || displayValue === "") onChange(0); else onChange(parsed); setDraftValue(null); }} className="input-field" placeholder="0.00" /></div>;
}

function CustomSelect({ value, onChange, options, label }: { value: string; onChange: (val: string) => void; options: Array<{ value: string; label: string }>; label?: string; }) {
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerId = useId();
  const labelId = useId();
  const listboxId = useId();
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const selectedOption = options[selectedIndex] || options[0];
  const openAtSelected = () => { setActiveIndex(selectedIndex); setIsOpen(true); };
  const selectActive = () => { const option = options[activeIndex]; if (option) onChange(option.value); setIsOpen(false); };
  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "ArrowDown") { event.preventDefault(); if (!isOpen) openAtSelected(); else setActiveIndex((index) => Math.min(options.length - 1, index + 1)); return; }
    if (event.key === "ArrowUp") { event.preventDefault(); if (!isOpen) openAtSelected(); else setActiveIndex((index) => Math.max(0, index - 1)); return; }
    if (event.key === "Home" && isOpen) { event.preventDefault(); setActiveIndex(0); return; }
    if (event.key === "End" && isOpen) { event.preventDefault(); setActiveIndex(Math.max(0, options.length - 1)); return; }
    if (event.key === "Escape" && isOpen) { event.preventDefault(); setIsOpen(false); return; }
    if ((event.key === "Enter" || event.key === " ") && isOpen) { event.preventDefault(); selectActive(); }
  };
  useEffect(() => { function handleClickOutside(e: MouseEvent) { if (containerRef.current && !containerRef.current.contains(e.target as Node)) setIsOpen(false); } document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside); }, []);
  return <div className="relative" ref={containerRef}>{label && <span id={labelId} className="block text-xs font-medium text-white/70 mb-1">{label}</span>}<button id={triggerId} type="button" role="combobox" aria-haspopup="listbox" aria-expanded={isOpen} aria-controls={listboxId} aria-labelledby={label ? `${labelId} ${triggerId}` : undefined} aria-label={label ? undefined : "Selecionar opção"} aria-activedescendant={isOpen && options[activeIndex] ? `${listboxId}-option-${activeIndex}` : undefined} onKeyDown={handleKeyDown} onClick={() => { if (isOpen) setIsOpen(false); else openAtSelected(); }} className="input-field text-left flex items-center justify-between gap-2 cursor-pointer bg-[#161225]/80 hover:bg-[#1c172e] transition-colors"><span className="truncate text-white font-medium text-xs sm:text-sm">{selectedOption?.label}</span><ChevronRight aria-hidden="true" className={cn("w-4 h-4 text-white/50 transition-transform duration-200 flex-shrink-0", isOpen && "rotate-90")} /></button>{isOpen && <div id={listboxId} role="listbox" aria-labelledby={label ? labelId : undefined} className="absolute top-full left-0 right-0 mt-1 z-50 bg-[#161225] border border-white/20 rounded-xl shadow-2xl overflow-hidden p-1 space-y-0.5 animate-fade-in backdrop-blur-2xl">{options.map((opt, index) => <button key={opt.value} id={`${listboxId}-option-${index}`} role="option" aria-selected={opt.value === value} tabIndex={-1} type="button" onMouseEnter={() => setActiveIndex(index)} onClick={() => { onChange(opt.value); setIsOpen(false); }} className={cn("w-full text-left px-3 py-2.5 rounded-lg text-xs font-medium transition-all flex items-center justify-between gap-2", index === activeIndex && "ring-1 ring-brand-primary/70", opt.value === value ? "bg-brand-primary text-white font-semibold shadow-md" : "text-white/80 hover:bg-white/10 hover:text-white")}><span className="truncate">{opt.label}</span>{opt.value === value && <Check aria-hidden="true" className="w-3.5 h-3.5 flex-shrink-0 text-white" />}</button>)}</div>}</div>;
}

